function evaluateBlockFunctions(condition) {
  let insideResult = null;
  let outsideHasTrue = false;

  if (condition) {
    function target() { return 'INSIDE_TRUE'; }
    insideResult = target();
  } else {
    function target() { return 'INSIDE_FALSE'; }
    insideResult = target();
  }

  return {
    insideResult,
    hasGlobalLeak: typeof target === 'function'
  };
}
